//! Rendering every generated file. Pure: the reconciler decides what to write.

pub mod dnsmasq;
pub mod launchd;
pub mod nginx;
pub mod php;
pub mod quote;
pub mod resolver;

use crate::brew::Brew;
use crate::{Paths, PhpVersion};
use std::path::{Path, PathBuf};

pub struct RenderCtx<'a> {
    pub paths: &'a Paths,
    pub brew: &'a Brew,
    pub tld: &'a str,
    pub http_port: u16,
    pub https_port: u16,
    pub timezone: &'a str,
}

/// First line of every `#`-comment generated file.
pub fn header(overrides: &Path) -> String {
    format!("# Generated by Yard — edit {} instead\n", overrides.display())
}

/// PHP's INI parser has rejected `#` comments since 7.0, so INI files use `;`.
pub fn ini_header(overrides: &Path) -> String {
    format!("; Generated by Yard — edit {} instead\n", overrides.display())
}

/// Where the header of the generated `file` sends edits, for `yard doctor`'s report of
/// hand-edited files. `None` for a path Yard does not generate.
pub fn overrides_for(paths: &Paths, file: &Path) -> Option<PathBuf> {
    if file == paths.nginx_conf() {
        return Some(paths.nginx_dir().join("overrides"));
    }
    if file == paths.nginx_default_index() {
        return Some(paths.sites_toml());
    }
    if file == paths.dnsmasq_conf() {
        return Some(paths.yard_toml());
    }
    let dir = file.parent()?;
    if dir.file_name()? == "conf.d" {
        // Mirrored brew inis and extension inis come from yard.toml's extensions.
        let v: PhpVersion = dir.parent()?.file_name()?.to_str()?.parse().ok()?;
        let name = file.file_name()?.to_str()?;
        let generated = name.starts_with("10-brew-") || name.starts_with("50-");
        return (dir == paths.php_conf_d(v) && generated).then(|| paths.yard_toml());
    }
    if dir == paths.nginx_sites_dir() {
        let name = file.file_stem()?.to_str()?;
        return Some(paths.nginx_override(name));
    }
    let v: PhpVersion = dir.file_name()?.to_str()?.parse().ok()?;
    (dir == paths.php_dir(v) && (file == paths.php_ini(v) || file == paths.fpm_conf(v)))
        .then(|| paths.php_overrides(v))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::brew::Brew;
    use crate::config::yard::{ExtEntry, ExtSource};
    use crate::{Paths, PhpVersion};
    use insta::assert_snapshot;
    use std::path::Path;
    use yard_proto::{SiteInfo, SiteKind, SiteSource};

    const ROOT: &str = "/Users/me/Library/Application Support/Yard";

    fn ctx_parts() -> (Paths, Brew) {
        (Paths::new(ROOT), Brew::new("/opt/homebrew"))
    }

    fn ctx<'a>(paths: &'a Paths, brew: &'a Brew) -> RenderCtx<'a> {
        RenderCtx { paths, brew, tld: "yard", http_port: 8080, https_port: 8443, timezone: "Asia/Manila" }
    }

    #[test]
    fn nginx_main_runs_in_the_foreground_as_the_user() {
        let (paths, brew) = ctx_parts();
        let conf = super::nginx::nginx_main(&ctx(&paths, &brew));
        assert!(conf.lines().any(|l| l.trim() == "daemon off;"), "yardd supervises it: {conf}");
        assert!(!conf.lines().any(|l| l.starts_with("user ")), "no root master to drop from: {conf}");
    }

    fn php_site(name: &str, path: &str) -> SiteInfo {
        SiteInfo {
            name: name.into(),
            host: format!("{name}.yard"),
            url: format!("http://{name}.yard:8080/"),
            source: SiteSource::Linked,
            kind: SiteKind::Php { path: path.into(), docroot: format!("{path}/public"), php: "8.4".into() },
            secure: false,
            project_file: None,
            needs: vec![],
            project_error: None,
        }
    }

    fn proxy_site() -> SiteInfo {
        SiteInfo {
            name: "api".into(),
            host: "api.yard".into(),
            url: "http://api.yard:8080/".into(),
            source: SiteSource::Proxy,
            kind: SiteKind::Proxy { target: "http://127.0.0.1:3000".into() },
            secure: false,
            project_file: None,
            needs: vec![],
            project_error: None,
        }
    }

    fn v(s: &str) -> PhpVersion {
        s.parse().unwrap()
    }

    #[test]
    fn nginx_main_trial() {
        let (p, b) = ctx_parts();
        assert_snapshot!(nginx::nginx_main(&ctx(&p, &b)));
    }

    #[test]
    fn nginx_site_php() {
        let (p, b) = ctx_parts();
        assert_snapshot!(nginx::nginx_site(&ctx(&p, &b), &php_site("blog", "/Users/me/Herd/blog")));
    }

    #[test]
    fn nginx_site_proxy() {
        let (p, b) = ctx_parts();
        assert_snapshot!(nginx::nginx_site(&ctx(&p, &b), &proxy_site()));
    }

    fn secure(mut site: SiteInfo) -> SiteInfo {
        site.secure = true;
        site.url = site.url.replace("http://", "https://").replace(":8080", ":8443");
        site
    }

    #[test]
    fn nginx_site_php_secure() {
        let (p, b) = ctx_parts();
        assert_snapshot!(nginx::nginx_site(&ctx(&p, &b), &secure(php_site("blog", "/Users/me/Herd/blog"))));
    }

    #[test]
    fn nginx_site_proxy_secure() {
        let (p, b) = ctx_parts();
        assert_snapshot!(nginx::nginx_site(&ctx(&p, &b), &secure(proxy_site())));
    }

    #[test]
    fn nginx_site_secure_on_443_redirects_without_a_port() {
        let (p, b) = ctx_parts();
        let c = RenderCtx { http_port: 80, https_port: 443, ..ctx(&p, &b) };
        let conf = nginx::nginx_site(&c, &secure(proxy_site()));
        assert!(conf.lines().any(|l| l.trim() == "return 301 https://$host$request_uri;"), "{conf}");
        assert!(conf.lines().any(|l| l.trim() == "listen 127.0.0.1:443 ssl;"), "{conf}");
        assert!(conf.lines().any(|l| l.trim() == "listen 127.0.0.1:80;"), "{conf}");
    }

    #[test]
    fn unknown_hosts_on_the_https_port_are_refused() {
        let (p, b) = ctx_parts();
        let conf = nginx::nginx_main(&ctx(&p, &b));
        let block = conf.split("server {").find(|b| b.contains(":8443 ssl default_server;")).expect(&conf);
        assert!(block.contains("listen [::1]:8443 ssl default_server;"), "{block}");
        assert!(block.lines().any(|l| l.trim() == "ssl_reject_handshake on;"), "{block}");
    }

    #[test]
    fn default_index_escapes_names() {
        let (p, b) = ctx_parts();
        let html = nginx::default_index(&ctx(&p, &b), &[php_site("<b>", "/x"), proxy_site()]);
        assert!(!html.contains("<b>"), "{html}");
        assert!(html.contains("&lt;b&gt;"), "{html}");
        assert_snapshot!(html);
    }

    #[test]
    fn php_ini_8_4() {
        let (p, b) = ctx_parts();
        assert_snapshot!(php::php_ini(&ctx(&p, &b), v("8.4")));
    }

    #[test]
    fn fpm_conf_8_4() {
        let (p, b) = ctx_parts();
        assert_snapshot!(php::fpm_conf(&ctx(&p, &b), v("8.4")));
    }

    #[test]
    fn fpm_conf_7_1_has_no_decorate() {
        let (p, b) = ctx_parts();
        let conf = php::fpm_conf(&ctx(&p, &b), v("7.1"));
        assert!(!conf.contains("decorate_workers_output"), "{conf}");
        assert!(php::fpm_conf(&ctx(&p, &b), v("7.3")).contains("decorate_workers_output = no"));
    }

    #[test]
    fn dnsmasq_conf_trial() {
        let (p, b) = ctx_parts();
        assert_snapshot!(dnsmasq::dnsmasq_conf(&ctx(&p, &b), 53535));
    }

    #[test]
    fn resolver_file_53535() {
        assert_eq!(resolver::resolver_file(53535), "# Managed by Yard\nnameserver 127.0.0.1\nport 53535\n");
    }

    #[test]
    fn daemon_plist_with_root() {
        let xml = launchd::daemon_plist(
            Path::new("/usr/local/bin/yardd"),
            Some(Path::new(ROOT)),
            Path::new("/tmp/yardd.log"),
        );
        assert_snapshot!(String::from_utf8(xml).unwrap());
        let without =
            launchd::daemon_plist(Path::new("/usr/local/bin/yardd"), None, Path::new("/tmp/yardd.log"));
        assert!(!String::from_utf8(without).unwrap().contains("YARD_ROOT"));
    }

    #[test]
    fn helper_plist() {
        let xml = launchd::helper_plist(
            Path::new("/Library/PrivilegedHelperTools/dev.more.yard.helper"),
            501,
            "me",
            Path::new(ROOT),
            Path::new("/opt/homebrew"),
        );
        assert_snapshot!(String::from_utf8(xml).unwrap());
    }

    #[test]
    fn renders_paths_with_spaces_quoted() {
        let (p, b) = ctx_parts();
        let c = ctx(&p, &b);
        let outputs = [
            nginx::nginx_main(&c),
            nginx::nginx_site(&c, &php_site("my-app", "/Users/me/Herd/my app")),
            nginx::nginx_site(&c, &secure(php_site("my-app", "/Users/me/Herd/my app"))),
            php::fpm_conf(&c, v("8.4")),
            php::php_ini(&c, v("8.4")),
        ];
        for out in &outputs {
            for line in out.lines().filter(|l| !l.starts_with('#') && !l.starts_with(';')) {
                for needle in ["Application Support", "my app"] {
                    if let Some(at) = line.find(needle) {
                        let before = line[..at].matches('"').count();
                        assert!(before % 2 == 1, "unquoted path in line: {line}");
                    }
                }
            }
        }
    }

    #[test]
    fn quoting_escapes_quotes_and_backslashes() {
        assert_eq!(quote::nginx_str(r#"/a "b"\c"#), r#""/a \"b\"\\c""#);
        assert_eq!(quote::ini_str("/a b"), "\"/a b\"");
    }

    #[test]
    fn every_generated_file_has_header() {
        let (p, b) = ctx_parts();
        let c = ctx(&p, &b);
        for out in
            [nginx::nginx_main(&c), nginx::nginx_site(&c, &proxy_site()), dnsmasq::dnsmasq_conf(&c, 53535)]
        {
            assert!(out.starts_with("# Generated by Yard — edit "), "{out}");
        }
        for out in [php::php_ini(&c, v("8.4")), php::fpm_conf(&c, v("8.4"))] {
            assert!(out.starts_with("; Generated by Yard — edit "), "{out}");
        }
        assert!(nginx::default_index(&c, &[]).starts_with("<!-- Generated by Yard — edit "));
    }

    #[test]
    fn overrides_for_names_the_path_each_header_names() {
        let (p, b) = ctx_parts();
        let c = ctx(&p, &b);
        let site = proxy_site();
        for (file, out) in [
            (p.nginx_conf(), nginx::nginx_main(&c)),
            (p.nginx_site(&site.name), nginx::nginx_site(&c, &site)),
            (p.nginx_default_index(), nginx::default_index(&c, &[])),
            (p.dnsmasq_conf(), dnsmasq::dnsmasq_conf(&c, 53535)),
            (p.php_ini(v("8.4")), php::php_ini(&c, v("8.4"))),
            (p.fpm_conf(v("8.4")), php::fpm_conf(&c, v("8.4"))),
            (
                p.php_conf_d(v("8.4")).join("50-redis.ini"),
                php::ext_ini(
                    &c,
                    "redis",
                    &ExtEntry { source: ExtSource::Brew, enabled: true, so: None },
                    &[],
                )
                .unwrap(),
            ),
            (
                p.php_conf_d(v("8.4")).join("10-brew-ext-opcache.ini"),
                php::brew_inis(&c, &[("ext-opcache.ini".into(), "x\n".into())], &Default::default())
                    .remove("10-brew-ext-opcache.ini")
                    .unwrap(),
            ),
        ] {
            let named = overrides_for(&p, &file).unwrap_or_else(|| panic!("{}", file.display()));
            let first = out.lines().next().unwrap();
            assert!(first.contains(&format!("edit {} instead", named.display())), "{first}");
        }
        assert_eq!(overrides_for(&p, &p.yard_toml()), None);
        assert_eq!(overrides_for(&p, &p.php_overrides(v("8.4"))), None);
    }
}
